window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-fc68e580191e48d1"]={"versions": [{"id": "FIG-fc68e580191e48d1", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Dateistruktur- und Inklusionsdiagramm (Header file structure) für das BSW-Modul Service Discovery (<code>SD</code>) innerhalb der AUTOSAR Classic Platform Schichtenarchitektur. Es stellt die C-Include-Beziehungen zwischen der Implementierungsdatei <code>SD.c</code>, modul-internen Header-Dateien sowie Schnittstellen-Headern benachbarter Basissoftware-Module dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende C-Quelldateien und Header-Module:</p>\n<ul class=\"fig-list\">\n<li><code>SD.c</code>: Zentrale Quellcodedatei des Service-Discovery-Moduls.</li>\n<li>Direkte Includes von <code>SD.c</code>:</li>\n<li><code>MemMap.h</code>: Speicherkonfigurations- und Mappingschnittstelle.</li>\n<li><code>SchM_SD.h</code>: Schedule-Manager-Header für BSW-Scheduler-Integration.</li>\n<li><code>SD.h</code>: Öffentlicher Haupt-Header des SD-Moduls.</li>\n<li><code>Det.h</code>: Schnittstelle zum Default Error Tracer.</li>\n<li><code>Dem.h</code>: Schnittstelle zum Diagnostic Event Manager.</li>\n<li><code>BswM.h</code>: Schnittstelle zum BSW Mode Manager.</li>\n<li><code>SoAd.h</code>: Schnittstelle zum Socket Adaptor.</li>\n<li>Weitere Inklusionsbeziehungen:</li>\n<li><code>SD.h</code> bindet <code>SD_Types.h</code> (Typdefinitionen) und <code>SD_Cfg.h</code> (Konfigurationsdeklarationen) ein.</li>\n<li><code>Dem.h</code> bindet <code>DemIntError.h</code> ein.</li>\n</ul>\n<p class=\"fig-p\">Alle Abhängigkeiten werden durch gestrichelte gerichtete Pfeile dargestellt, die von der inkludierenden Datei auf die inkludierte Header-Datei zeigen.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Compile-Time-Abhängigkeitsdiagramm ohne zeitlichen Dynamik- oder Sequenzablauf. Die Pfeile repräsentieren <code>#include</code>-Präprozessordirektiven zur Definitions- und Deklarationsauflösung während des Übersetzungsvorgangs.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe zur Modulstruktur und Inklusionshierarchie des Service-Discovery-Treibers:</p>\n<ul class=\"fig-list\">\n<li><code>SD.c</code> darf externe Module (<code>Det.h</code>, <code>Dem.h</code>, <code>BswM.h</code>, <code>SoAd.h</code>) sowie die eigenen internen Header und Scheduler-/Memory-Header inkludieren.</li>\n<li>Externe Modulinformationen für Typen und Konfiguration des SD-Moduls werden über <code>SD.h</code> hierarchisch gekapselt (<code>SD_Types.h</code>, <code>SD_Cfg.h</code>).</li>\n<li>Fehlerbehandlungscodes des DEM müssen über <code>DemIntError.h</code> via <code>Dem.h</code> bezogen werden. Die Inklusionspfade sind verbindlich bei der Modulimplementierung einzuhalten.</li>\n</ul>"}, {"id": "FIG-5a380a0715724f1d", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Dateistruktur- und Inklusionsdiagramm (Header file structure) für das BSW-Modul Service Discovery (<code>SD</code>) innerhalb der AUTOSAR Classic Platform Schichtenarchitektur. Es stellt die C-Include-Beziehungen zwischen der Implementierungsdatei <code>SD.c</code>, modul-internen Header-Dateien sowie Schnittstellen-Headern benachbarter Basissoftware-Module dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende C-Quelldateien und Header-Module:</p>\n<ul class=\"fig-list\">\n<li><code>SD.c</code>: Zentrale Quellcodedatei des Service-Discovery-Moduls.</li>\n<li>Direkte Includes von <code>SD.c</code>:</li>\n<li><code>MemMap.h</code>: Speicherkonfigurations- und Mappingschnittstelle.</li>\n<li><code>SchM_SD.h</code>: Schedule-Manager-Header für BSW-Scheduler-Integration.</li>\n<li><code>SD.h</code>: Öffentlicher Haupt-Header des SD-Moduls.</li>\n<li><code>Det.h</code>: Schnittstelle zum Default Error Tracer.</li>\n<li><code>Dem.h</code>: Schnittstelle zum Diagnostic Event Manager.</li>\n<li><code>BswM.h</code>: Schnittstelle zum BSW Mode Manager.</li>\n<li><code>SoAd.h</code>: Schnittstelle zum Socket Adaptor.</li>\n<li>Weitere Inklusionsbeziehungen:</li>\n<li><code>SD.h</code> bindet <code>SD_Types.h</code> (Typdefinitionen) und <code>SD_Cfg.h</code> (Konfigurationsdeklarationen) ein.</li>\n<li><code>Dem.h</code> bindet <code>Dem_IntErrId.h</code> ein.</li>\n<li><code>SoAd.h</code> bindet <code>SoAd_Types.h</code>, <code>SoAd_Cfg.h</code>, <code>TcpIp_Types.h</code> und <code>ComStack_Types.h</code> ein.</li>\n<li><code>ComStack_Types.h</code> bindet <code>Std_Types.h</code> ein.</li>\n</ul>\n<p class=\"fig-p\">Alle Abhängigkeiten werden durch gestrichelte gerichtete Pfeile dargestellt, die von der inkludierenden Datei auf die inkludierte Header-Datei zeigen.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Compile-Time-Abhängigkeitsdiagramm ohne zeitlichen Dynamik- oder Sequenzablauf. Die Pfeile repräsentieren <code>#include</code>-Präprozessordirektiven zur Definitions- und Deklarationsauflösung während des Übersetzungsvorgangs.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe zur Modulstruktur und Inklusionshierarchie des Service-Discovery-Treibers:</p>\n<ul class=\"fig-list\">\n<li><code>SD.c</code> inkludiert die Systemschnittstellen <code>MemMap.h</code>, <code>SchM_SD.h</code>, <code>SD.h</code>, <code>Det.h</code>, <code>Dem.h</code>, <code>BswM.h</code> und <code>SoAd.h</code>.</li>\n<li>Modulinterne Typen und Konfigurationen werden über <code>SD.h</code> bereitgestellt (<code>SD_Types.h</code>, <code>SD_Cfg.h</code>).</li>\n<li><code>SoAd.h</code> kapselt die transitive Inklusion von <code>TcpIp_Types.h</code>, <code>SoAd_Cfg.h</code>, <code>SoAd_Types.h</code> sowie <code>ComStack_Types.h</code> (welches wiederum <code>Std_Types.h</code> einbindet).</li>\n<li>Diagnose-Fehlerbezeichner des DEM werden über <code>Dem_IntErrId.h</code> via <code>Dem.h</code> eingebunden. Die Inklusionskette ist verbindlich für die Übersetzungskonfiguration.</li>\n</ul>"}], "trans": [{"from": "FIG-fc68e580191e48d1", "to": "FIG-5a380a0715724f1d", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Neuer Header <code>TcpIp_Types.h</code>: wird von <code>SoAd.h</code> eingebunden.</li>\n<li>Neuer Header <code>ComStack_Types.h</code>: wird von <code>SoAd.h</code> eingebunden.</li>\n<li>Neuer Header <code>Std_Types.h</code>: wird von <code>ComStack_Types.h</code> eingebunden.</li>\n<li>Neuer Header <code>SoAd_Cfg.h</code>: wird von <code>SoAd.h</code> eingebunden.</li>\n<li>Neuer Header <code>SoAd_Types.h</code>: wird von <code>SoAd.h</code> eingebunden.</li>\n<li>Element <code>DemIntError.h</code> umbenannt zu <code>Dem_IntErrId.h</code> (weiterhin eingebunden von <code>Dem.h</code>).</li>\n</ul>"}]};
